BEGIN;

UPDATE public.questions q
SET explanation_data = q.explanation_data || jsonb_build_object('viz', '<svg viewBox="0 0 340 190" xmlns="http://www.w3.org/2000/svg"><text x="170" y="14" font-size="10" fill="#e8eaf0" text-anchor="middle" font-weight="600">イメージのレイヤー構造</text><rect x="54" y="108" width="166" height="22" rx="4" fill="#1a1e29" stroke="#2a2f3f" stroke-width="1"/><text x="137.0" y="122" font-size="9" fill="#8892a4" text-anchor="middle" font-weight="normal">L1: FROM ubuntu</text><text x="46" y="123" font-size="7" fill="#8892a4" text-anchor="end" font-weight="normal">読取専用</text><rect x="54" y="82" width="166" height="22" rx="4" fill="#1a1e29" stroke="#2a2f3f" stroke-width="1"/><text x="137.0" y="96" font-size="9" fill="#8892a4" text-anchor="middle" font-weight="normal">L2: RUN apt install</text><text x="46" y="97" font-size="7" fill="#8892a4" text-anchor="end" font-weight="normal">読取専用</text><rect x="54" y="56" width="166" height="22" rx="4" fill="#1a1e29" stroke="#2a2f3f" stroke-width="1"/><text x="137.0" y="70" font-size="9" fill="#8892a4" text-anchor="middle" font-weight="normal">L3: COPY app.py</text><text x="46" y="71" font-size="7" fill="#8892a4" text-anchor="end" font-weight="normal">読取専用</text><rect x="54" y="30" width="166" height="22" rx="4" fill="#232a1f" stroke="#6ab08d" stroke-width="1"/><text x="137.0" y="44" font-size="9" fill="#6ab08d" text-anchor="middle" font-weight="normal">コンテナ層（書き込み可）</text><text x="46" y="45" font-size="7" fill="#6ab08d" text-anchor="end" font-weight="normal">書込み可</text><line x1="250" y1="93.0" x2="250" y2="41.0" stroke="#c9a04a" stroke-width="1.3" stroke-dasharray="3,2"/><line x1="220" y1="93.0" x2="250" y2="93.0" stroke="#c9a04a" stroke-width="1.3" stroke-dasharray="3,2"/><line x1="250" y1="41.0" x2="220" y2="41.0" stroke="#c9a04a" stroke-width="1.3" stroke-dasharray="3,2"/><text x="256" y="83.0" font-size="7" fill="#c9a04a" text-anchor="start" font-weight="normal">変更したいファイルだけ</text><text x="256" y="95.0" font-size="7" fill="#c9a04a" text-anchor="start" font-weight="normal">コピーしてから書き換える</text><text x="170" y="178" font-size="8" fill="#8892a4" text-anchor="middle" font-weight="normal">＝ Copy-on-Write。下の層は誰も傷つけない</text></svg>')
WHERE q.source_ref = 'dca-q40'
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'dca');

UPDATE public.questions q
SET explanation_data = q.explanation_data || jsonb_build_object('viz', '<svg viewBox="0 0 340 168" xmlns="http://www.w3.org/2000/svg"><text x="170" y="14" font-size="10" fill="#e8eaf0" text-anchor="middle" font-weight="600">マルチステージビルド</text><rect x="10" y="30" width="150" height="100" rx="4" fill="#1a1e29" stroke="#2a2f3f" stroke-width="1"/><text x="85.0" y="46" font-size="9" fill="#8892a4" text-anchor="middle" font-weight="600">ビルドステージ (golang)</text><rect x="20" y="64" width="130" height="16" rx="4" fill="#241a1a" stroke="#c47070" stroke-width="1"/><text x="85.0" y="75" font-size="8" fill="#c47070" text-anchor="middle" font-weight="normal">Goコンパイラ</text><rect x="20" y="84" width="130" height="16" rx="4" fill="#241a1a" stroke="#c47070" stroke-width="1"/><text x="85.0" y="95" font-size="8" fill="#c47070" text-anchor="middle" font-weight="normal">ソースコード</text><rect x="20" y="104" width="130" height="16" rx="4" fill="#241a1a" stroke="#c47070" stroke-width="1"/><text x="85.0" y="115" font-size="8" fill="#c47070" text-anchor="middle" font-weight="normal">ビルド中間ファイル</text><text x="85.0" y="144" font-size="8" fill="#c47070" text-anchor="middle" font-weight="normal">最終イメージには残らない</text><rect x="200" y="30" width="150" height="100" rx="4" fill="#1a1e29" stroke="#6ab08d" stroke-width="1"/><text x="275.0" y="46" font-size="9" fill="#8892a4" text-anchor="middle" font-weight="600">最終ステージ (alpine)</text><rect x="210" y="70" width="130" height="22" rx="4" fill="#232a1f" stroke="#6ab08d" stroke-width="1"/><text x="275.0" y="84" font-size="9" fill="#6ab08d" text-anchor="middle" font-weight="normal">実行ファイルだけ</text><text x="275.0" y="144" font-size="8" fill="#6ab08d" text-anchor="middle" font-weight="normal">軽い・攻撃面も小さい</text><line x1="160" y1="81" x2="200" y2="81" stroke="#3b82f6" stroke-width="1.3"/><text x="180.0" y="75" font-size="7" fill="#60a5fa" text-anchor="middle" font-weight="normal">COPY --from=builder</text></svg>')
WHERE q.source_ref = 'dca-q7'
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'dca');

UPDATE public.questions q
SET explanation_data = q.explanation_data || jsonb_build_object('viz', '<svg viewBox="0 0 340 195" xmlns="http://www.w3.org/2000/svg"><text x="170" y="14" font-size="10" fill="#e8eaf0" text-anchor="middle" font-weight="600">COPY の順番とキャッシュの壊れ方</text><text x="85.0" y="30" font-size="9" fill="#6ab08d" text-anchor="middle" font-weight="600">良い順番</text><rect x="10" y="40" width="150" height="20" rx="4" fill="#232a1f" stroke="#6ab08d" stroke-width="1"/><text x="85.0" y="53" font-size="8" fill="#e8eaf0" text-anchor="middle" font-weight="normal">COPY requirements.txt .</text><text x="85.0" y="40" font-size="1" fill="#8892a4" text-anchor="middle" font-weight="normal"></text><rect x="10" y="66" width="150" height="20" rx="4" fill="#232a1f" stroke="#6ab08d" stroke-width="1"/><text x="85.0" y="79" font-size="8" fill="#e8eaf0" text-anchor="middle" font-weight="normal">RUN pip install</text><text x="85.0" y="66" font-size="1" fill="#8892a4" text-anchor="middle" font-weight="normal"></text><rect x="10" y="92" width="150" height="20" rx="4" fill="#2a2416" stroke="#c9a04a" stroke-width="1"/><text x="85.0" y="105" font-size="8" fill="#e8eaf0" text-anchor="middle" font-weight="normal">COPY . .  ← コードを変更</text><text x="85.0" y="124" font-size="1" fill="#8892a4" text-anchor="middle" font-weight="normal"></text><text x="85.0" y="112" font-size="8" fill="#6ab08d" text-anchor="middle" font-weight="normal">依存インストールは再利用される</text><text x="255.0" y="30" font-size="9" fill="#c47070" text-anchor="middle" font-weight="600">悪い順番</text><rect x="180" y="40" width="150" height="20" rx="4" fill="#241a1a" stroke="#c47070" stroke-width="1"/><text x="255.0" y="53" font-size="8" fill="#e8eaf0" text-anchor="middle" font-weight="normal">COPY . .  ← コードを変更</text><rect x="180" y="66" width="150" height="20" rx="4" fill="#241a1a" stroke="#c47070" stroke-width="1"/><text x="255.0" y="79" font-size="8" fill="#e8eaf0" text-anchor="middle" font-weight="normal">RUN pip install</text><text x="255.0" y="112" font-size="8" fill="#c47070" text-anchor="middle" font-weight="normal">コード1行の変更で</text><text x="255.0" y="124" font-size="8" fill="#c47070" text-anchor="middle" font-weight="normal">依存インストールもやり直し</text><text x="170" y="182" font-size="8" fill="#8892a4" text-anchor="middle" font-weight="normal">COPYした内容が変わった行から下は、キャッシュが全部無効になる</text></svg>')
WHERE q.source_ref = 'dca-q8'
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'dca');

UPDATE public.questions q
SET explanation_data = q.explanation_data || jsonb_build_object('viz', '<svg viewBox="0 0 340 158" xmlns="http://www.w3.org/2000/svg"><text x="170" y="14" font-size="9.5" fill="#e8eaf0" text-anchor="middle" font-weight="600">タグは動く貼り紙、ダイジェストは中身そのもの</text><text x="85" y="34" font-size="9" fill="#60a5fa" text-anchor="middle" font-weight="600">タグ (v1.2)</text><rect x="30" y="44" width="60" height="26" rx="4" fill="#20263a" stroke="#3b82f6" stroke-width="1"/><text x="60" y="61" font-size="8" fill="#e8eaf0" text-anchor="middle" font-weight="normal">v1.2 の貼り紙</text><line x1="60" y1="70" x2="60" y2="86" stroke="#3b82f6" stroke-width="1.3" stroke-dasharray="3,2"/><rect x="30" y="88" width="60" height="24" rx="4" fill="#1a1e29" stroke="#2a2f3f" stroke-width="1"/><text x="60" y="103" font-size="8" fill="#8892a4" text-anchor="middle" font-weight="normal">中身A（今日）</text><text x="60" y="122" font-size="7" fill="#c9a04a" text-anchor="middle" font-weight="normal">貼り直せば</text><text x="60" y="133" font-size="7" fill="#c9a04a" text-anchor="middle" font-weight="normal">別の中身も指せる</text><text x="255" y="34" font-size="9" fill="#6ab08d" text-anchor="middle" font-weight="600">ダイジェスト (sha256:...)</text><rect x="200" y="44" width="110" height="26" rx="4" fill="#232a1f" stroke="#6ab08d" stroke-width="1"/><text x="255" y="61" font-size="8" fill="#e8eaf0" text-anchor="middle" font-weight="normal">sha256:9f3a...</text><line x1="255" y1="70" x2="255" y2="86" stroke="#6ab08d" stroke-width="1.3"/><rect x="225" y="88" width="60" height="24" rx="4" fill="#1a1e29" stroke="#2a2f3f" stroke-width="1"/><text x="255" y="103" font-size="8" fill="#8892a4" text-anchor="middle" font-weight="normal">中身A固定</text><text x="255" y="122" font-size="7" fill="#6ab08d" text-anchor="middle" font-weight="normal">中身が変われば</text><text x="255" y="133" font-size="7" fill="#6ab08d" text-anchor="middle" font-weight="normal">値も必ず変わる</text><text x="170" y="150" font-size="8" fill="#8892a4" text-anchor="middle" font-weight="normal">本番の再現性を守りたいならダイジェストで固定する</text></svg>')
WHERE q.source_ref = 'dca-q10'
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'dca');

UPDATE public.questions q
SET explanation_data = q.explanation_data || jsonb_build_object('viz', '<svg viewBox="0 0 340 150" xmlns="http://www.w3.org/2000/svg"><text x="170" y="14" font-size="9.5" fill="#e8eaf0" text-anchor="middle" font-weight="600">ENTRYPOINT は固定、CMD は既定の引数</text><rect x="20" y="32" width="130" height="26" rx="4" fill="#20263a" stroke="#3b82f6" stroke-width="1"/><text x="85" y="49" font-size="8" fill="#60a5fa" text-anchor="middle" font-weight="normal">ENTRYPOINT ["python"]</text><text x="85" y="66" font-size="7" fill="#8892a4" text-anchor="middle" font-weight="normal">固定・変わらない</text><rect x="190" y="32" width="130" height="26" rx="4" fill="#232a1f" stroke="#6ab08d" stroke-width="1"/><text x="255" y="49" font-size="8" fill="#6ab08d" text-anchor="middle" font-weight="normal">CMD ["app.py"]</text><text x="255" y="66" font-size="7" fill="#8892a4" text-anchor="middle" font-weight="normal">既定の引数（差し替え可）</text><text x="170" y="90" font-size="8" fill="#e8eaf0" text-anchor="middle" font-weight="normal">docker run <image>  →  python app.py</text><rect x="190" y="104" width="130" height="26" rx="4" fill="#2a2416" stroke="#c9a04a" stroke-width="1"/><text x="255" y="121" font-size="8" fill="#c9a04a" text-anchor="middle" font-weight="normal">CMD ["test.py"]</text><text x="255" y="138" font-size="7" fill="#c9a04a" text-anchor="middle" font-weight="normal">runの引数でここだけ置き換わる</text><text x="85" y="121" font-size="8" fill="#8892a4" text-anchor="middle" font-weight="normal">ENTRYPOINT はそのまま</text><text x="170" y="148" font-size="7.5" fill="#8892a4" text-anchor="middle" font-weight="normal">docker run <image> test.py  →  python test.py</text></svg>')
WHERE q.source_ref = 'dca-q11'
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'dca');

UPDATE public.questions q
SET explanation_data = q.explanation_data || jsonb_build_object('viz', '<svg viewBox="0 0 340 168" xmlns="http://www.w3.org/2000/svg"><text x="170" y="14" font-size="9" fill="#e8eaf0" text-anchor="middle" font-weight="600">save はイメージ丸ごと、export はコンテナの中身だけ</text><text x="85" y="34" font-size="9" fill="#60a5fa" text-anchor="middle" font-weight="600">docker save</text><rect x="20" y="42" width="130" height="46" rx="4" fill="#20263a" stroke="#3b82f6" stroke-width="1"/><text x="85" y="56" font-size="8" fill="#e8eaf0" text-anchor="middle" font-weight="normal">イメージ（3層）</text><text x="85" y="68" font-size="7" fill="#8892a4" text-anchor="middle" font-weight="normal">レイヤー構造・タグ</text><text x="85" y="80" font-size="7" fill="#8892a4" text-anchor="middle" font-weight="normal">履歴つき</text><line x1="85" y1="88" x2="85" y2="100" stroke="#3b82f6" stroke-width="1.3"/><rect x="35" y="102" width="100" height="20" rx="4" fill="#1a1e29" stroke="#3b82f6" stroke-width="1"/><text x="85" y="116" font-size="7.5" fill="#60a5fa" text-anchor="middle" font-weight="normal">tar（丸ごと復元可）</text><text x="255" y="34" font-size="9" fill="#6ab08d" text-anchor="middle" font-weight="600">docker export</text><rect x="190" y="42" width="130" height="46" rx="4" fill="#232a1f" stroke="#6ab08d" stroke-width="1"/><text x="255" y="56" font-size="8" fill="#e8eaf0" text-anchor="middle" font-weight="normal">動いているコンテナ</text><text x="255" y="68" font-size="7" fill="#8892a4" text-anchor="middle" font-weight="normal">中のファイル一式</text><text x="255" y="80" font-size="7" fill="#8892a4" text-anchor="middle" font-weight="normal">履歴なし・平ら</text><line x1="255" y1="88" x2="255" y2="100" stroke="#6ab08d" stroke-width="1.3"/><rect x="205" y="102" width="100" height="20" rx="4" fill="#1a1e29" stroke="#6ab08d" stroke-width="1"/><text x="255" y="116" font-size="7.5" fill="#6ab08d" text-anchor="middle" font-weight="normal">tar（構造は消える）</text><text x="170" y="148" font-size="8" fill="#8892a4" text-anchor="middle" font-weight="normal">本棚ごと梱包(save) vs 本だけ取り出す(export)</text></svg>')
WHERE q.source_ref = 'dca-q38'
  AND q.subject_id = (SELECT id FROM public.subjects WHERE slug = 'dca');

COMMIT;